-- ============================================================================
-- Authoritative legacy correction — sourced from the OLD production server
--   Old server: 196.43.168.55  (phpMyAdmin :8080, DB `muteesa`, legacy schema)
--   Truth sources:  gensubject.subcu  (credit units, mode per code)
--                   stbsubject.sbjname (subject names)
-- ----------------------------------------------------------------------------
-- WHY: the pre-ERP import kept course CODES but neither names nor real credit
-- units. An earlier backfill guessed a uniform CU=3; the old server proves the
-- real units vary (4/5/2/…). This script loads the old server's authoritative
-- CU + name maps and applies them to the LEGACY (course_state='ARCHIVED') rows
-- only — modern catalogue courses are never touched.
--
-- RESULT (run 2026-07-29): 2,693 result rows recorrected across 726 students;
-- 873 legacy courses given their real name; per-semester GPA + CGPA recomputed.
-- Backups: bak_oldserver_fix_20260729 (results) + bak_oldserver_course_20260729.
--
-- NAMES THAT DO NOT EXIST ANYWHERE: 252 codes remain code=name — dominated by
-- the Ordinary Diploma families ODC/ODM/ODE (+SWS). Verified absent even in the
-- old server's own name master (stbsubject) and curriculum (genpgmsubject);
-- they were never digitised. See sql/legacy_names_never_existed.csv.
--
-- The two INSERT blocks below carry the old server's data inline so this script
-- is self-contained and reproducible without re-crawling the old host.
-- ============================================================================
USE campus_dynamics;
DROP TEMPORARY TABLE IF EXISTS old_cu;
CREATE TEMPORARY TABLE old_cu (code CHAR(25) CHARACTER SET utf8 COLLATE utf8_general_ci PRIMARY KEY, cu DOUBLE) ENGINE=MEMORY;
