-- ===== BACKUP everything about to change =====
DROP TABLE IF EXISTS bak_oldserver_fix_20260729;
CREATE TABLE bak_oldserver_fix_20260729 (
  src VARCHAR(30), ID INT, regno VARCHAR(100), courseid CHAR(25),
  studyyear INT, semester INT, CreditUnits DOUBLE, gpa DOUBLE,
  KEY k(src,ID), KEY k2(regno,studyyear,semester)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
INSERT INTO bak_oldserver_fix_20260729
  SELECT 'acad_results', r.ID, r.regno, r.courseid, r.studyyear, r.semester, r.CreditUnits, r.gpa
    FROM acad_results r JOIN old_cu m ON m.code=r.courseid
   WHERE r.courseid IN (SELECT courseID FROM acad_course WHERE course_state='ARCHIVED');
INSERT INTO bak_oldserver_fix_20260729
  SELECT 'acad_transcript_results', t.ID, t.regno, t.courseid, t.studyyear, t.semester, t.CreditUnits, t.gpa
    FROM acad_transcript_results t JOIN old_cu m ON m.code=t.courseid
   WHERE t.courseid IN (SELECT courseID FROM acad_course WHERE course_state='ARCHIVED');

DROP TABLE IF EXISTS bak_oldserver_course_20260729;
CREATE TABLE bak_oldserver_course_20260729 AS
  SELECT courseID, courseName, CreditUnit FROM acad_course WHERE course_state='ARCHIVED';

-- ===== 1. authoritative CREDIT UNITS on the legacy catalogue rows =====
UPDATE acad_course c JOIN old_cu m ON m.code=c.courseID
   SET c.CreditUnit=m.cu
 WHERE c.course_state='ARCHIVED' AND m.cu>0 AND c.CreditUnit<>m.cu;

-- ===== 2. real NAMES recovered from the old name master (placeholder rows only) =====
UPDATE acad_course c JOIN old_name n ON n.ncode=UPPER(REPLACE(REPLACE(REPLACE(c.courseID,' ',''),':',''),'-',''))
   SET c.courseName=n.nm
 WHERE c.course_state='ARCHIVED' AND BINARY c.courseName=BINARY c.courseID;

-- ===== 3. push authoritative CU into the result rows (legacy codes only) =====
UPDATE acad_results r JOIN old_cu m ON m.code=r.courseid
   SET r.CreditUnits=m.cu
 WHERE r.courseid IN (SELECT courseID FROM acad_course WHERE course_state='ARCHIVED') AND m.cu>0;
UPDATE acad_transcript_results t JOIN old_cu m ON m.code=t.courseid
   SET t.CreditUnits=m.cu
 WHERE t.courseid IN (SELECT courseID FROM acad_course WHERE course_state='ARCHIVED') AND m.cu>0;

-- ===== 4. recompute stored semester GPA for every affected student =====
DROP TABLE IF EXISTS wk_sg;
CREATE TABLE wk_sg (regno VARCHAR(100), studyyear INT, semester INT, sem_gpa DOUBLE,
                    KEY k(regno,studyyear,semester)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
INSERT INTO wk_sg
  SELECT r.regno, r.studyyear, r.semester,
         ROUND(SUM(r.gradept*r.CreditUnits)/NULLIF(SUM(r.CreditUnits),0),2)
    FROM acad_results r
    JOIN (SELECT DISTINCT regno FROM bak_oldserver_fix_20260729) a ON a.regno=r.regno
   GROUP BY r.regno, r.studyyear, r.semester;
UPDATE acad_results r JOIN wk_sg g ON g.regno=r.regno AND g.studyyear=r.studyyear AND g.semester=r.semester
   SET r.gpa=g.sem_gpa WHERE g.sem_gpa IS NOT NULL;
UPDATE acad_transcript_results t JOIN wk_sg g ON g.regno=t.regno AND g.studyyear=t.studyyear AND g.semester=t.semester
   SET t.gpa=g.sem_gpa WHERE g.sem_gpa IS NOT NULL;
DROP TABLE wk_sg;

SELECT 'DONE' status,
  (SELECT COUNT(*) FROM bak_oldserver_fix_20260729) rows_backed,
  (SELECT COUNT(DISTINCT regno) FROM bak_oldserver_fix_20260729) students,
  (SELECT COUNT(*) FROM acad_course WHERE course_state='ARCHIVED' AND BINARY courseName<>BINARY courseID) named_now;
